const msg = $json.message || {};
const text = (msg.text || '').toString().trim();
const chatId = msg.chat ? msg.chat.id : null;

if (text === '/start' || text === '/help') {
  const help = '/start e /help: esta ajuda\n' + '1. Link do GitHub: analiso o repositório.\n' + '2. Link da Play Store ou App Store: analiso o app.\n' + '3. Qualquer outra URL: leio a página.\n' + '4. Informação atual (notícias, preços, docs): busco na web.\n' + 'Tarefas curtas usam o modelo rápido; complexas usam o modelo forte, automaticamente.';
  return [ { json: { chatId, text: help, route: 'resposta' } } ];
}

const heavy = /(analis|desenvolv|criar|crie|planej|arquitetur|compar|debug|testar|teste|refator|codigo|código|script|funcao|função|melhor|otimiz)/i;
const isComplex = text.length > 140 || heavy.test(text) || text.includes('http') || text.includes('github');
return [ { json: { chatId, text, route: isComplex ? 'completo' : 'rapido' } } ];

// Code validation/execution tool.
// The LLM passes the JavaScript source to test via "query".
const source = String(query);

// Reject ESM-only syntax gracefully (new Function cannot parse import/export).
if (/^(imports?\s|export\s)/m.test(source) || /\bimport\s*\(/.test(source)) {
  return JSON.stringify({
    syntaxValid: false,
    executed: false,
    error: "ESM import/export is not supported by the test runner. Please check the code without module syntax.",
  });
}

try {
  // Syntax check: build the function without executing it.
  const fn = new Function(source);
  let execResult;
  let executed = false;
  try {
    execResult = fn();
    executed = true;
  } catch (runErr) {
    return JSON.stringify({
      syntaxValid: true,
      executed: false,
      runtimeError: String(runErr && runErr.message ? runErr.message : runErr),
    });
  }
  return JSON.stringify({
    syntaxValid: true,
    executed,
    result: typeof execResult === 'undefined' ? null : execResult,
  });
} catch (syntaxErr) {
  return JSON.stringify({
    syntaxValid: false,
    executed: false,
    error: String(syntaxErr && syntaxErr.message ? syntaxErr.message : syntaxErr),
  });
}

const raw = String($json.output || $json.text || '');
const chatId = $json.chatId || $('Telegram Trigger').item.json.message.chat.id;
const LIMIT = 3900;

const chunks = [];
let rest = raw;
while (rest.length > LIMIT) {
  let cut = rest.lastIndexOf('\n', LIMIT);
  if (cut < LIMIT * 0.5) cut = rest.lastIndexOf(' ', LIMIT);
  if (cut < LIMIT * 0.5) cut = LIMIT;
  chunks.push(rest.slice(0, cut).trim());
  rest = rest.slice(cut).trim();
}
if (rest) chunks.push(rest);
if (chunks.length === 0) chunks.push('Desculpe, não consegui gerar uma resposta agora. Tente novamente.');
return chunks.map(text => ({ json: { chatId, text } }));
